/**
 * Toroidal Cognitive Service
 *
 * Produces a ToroidalDialogue in which the Deep Tree Echo response, the Marduk
 * response and the synchronized reflection are each generated by the language
 * model (via DeepTreeEchoOpenAIService and its toroidal persona prompts).
 * Nothing is generated locally: when no model is configured or a call fails
 * the error propagates to the caller.
 */
import { useMemory } from "../contexts/MemoryContext";
import { DeepTreeEchoOpenAIService } from "./openaiService";
import { DeepTreeEchoService } from "./deepTreeEchoService";
import MardukScientistService from "./mardukScientistService";
import { renderPromptTemplate } from "./promptTemplates";
import {
  PersonaConfig,
  PersonaResponse,
  ToroidalCognitiveOptions,
  ToroidalDialogue,
} from "../types/ToroidalCognitive";

export type ToroidalResponse = ToroidalDialogue;
export type ToroidalOptions = ToroidalCognitiveOptions;

type Synergy = NonNullable<ToroidalDialogue["reflection"]>["synergy"];

const SYNERGY_VALUES = ["convergent", "divergent", "complementary"] as const;

export class ToroidalCognitiveService {
  private static instance: ToroidalCognitiveService;

  private constructor() {}

  public static getInstance(): ToroidalCognitiveService {
    if (!ToroidalCognitiveService.instance) {
      ToroidalCognitiveService.instance = new ToroidalCognitiveService();
    }
    return ToroidalCognitiveService.instance;
  }

  private get openai(): DeepTreeEchoOpenAIService {
    return DeepTreeEchoOpenAIService.getInstance();
  }

  public setApiKey(key: string): void {
    this.openai.setApiKey(key);
  }

  public hasApiKey(): boolean {
    return this.openai.hasApiKey();
  }

  /**
   * Generate the full dual-persona dialogue with the model.
   *
   * @param memoryContext Optional memory snippets supplied to both personas.
   */
  public async generateToroidalDialogue(
    query: string,
    options: ToroidalCognitiveOptions = {},
    memoryContext: string[] = []
  ): Promise<ToroidalDialogue> {
    const start = Date.now();
    const contextType = options.creativityLevel ?? "balanced";

    const [deepTreeEchoResponse, mardukResponse] = await Promise.all([
      this.generatePersonaResponse(
        "deepTreeEcho",
        query,
        options,
        memoryContext
      ),
      this.generatePersonaResponse("marduk", query, options, memoryContext),
    ]);

    const dialogue: ToroidalDialogue = {
      deepTreeEchoResponse,
      mardukResponse,
      metadata: {
        queryId: `toroidal_${start}_${Math.random().toString(36).slice(2, 9)}`,
        totalProcessingTime: 0,
        contextType,
      },
    };

    if (options.includeReflection !== false) {
      dialogue.reflection = await this.generateReflection(
        query,
        deepTreeEchoResponse.content,
        mardukResponse.content,
        options
      );
    }

    dialogue.metadata.totalProcessingTime = Date.now() - start;
    return dialogue;
  }

  /**
   * Opening introduction when the toroidal chat is first opened: Echo's
   * greeting, Marduk's greeting and a joint welcome, each written by the model
   * from the greeting prompt templates.
   */
  public async generateIntroductionDialogue(
    options: ToroidalCognitiveOptions & { storedMemoryCount?: number } = {}
  ): Promise<ToroidalDialogue> {
    const start = Date.now();
    const timed = async (
      persona: PersonaResponse["persona"],
      run: () => Promise<string>
    ): Promise<PersonaResponse> => {
      const t0 = Date.now();
      const content = await run();
      return {
        persona,
        content,
        timestamp: new Date(),
        processingTime: Date.now() - t0,
      };
    };

    const [deepTreeEchoResponse, mardukResponse] = await Promise.all([
      timed("deepTreeEcho", () =>
        DeepTreeEchoService.getInstance().generateGreeting({
          toroidalMode: true,
          storedMemoryCount: options.storedMemoryCount,
          creativityLevel: options.creativityLevel,
        })
      ),
      timed("marduk", () =>
        MardukScientistService.getInstance().generateResponse(
          "(The user opened the chat.)",
          { intent: "greeting", maxTokens: 200, temperature: 0.7 }
        )
      ),
    ]);

    const welcome = await this.openai.generateResponse(
      `Deep Tree Echo said:\n${deepTreeEchoResponse.content}\n\nMarduk said:\n${mardukResponse.content}`,
      {
        toroidalMode: "synced",
        creativityLevel: options.creativityLevel,
        maxTokens: 200,
        systemPrompt: renderPromptTemplate({
          id: "toroidal-welcome",
          purpose:
            "The user just opened the toroidal chat. Write the joint welcome that follows the two greetings above.",
          structure: [
            "Do NOT use the **Echo:** / **Marduk:** sections for this message; write 2-3 unified sentences.",
            "Say how intuition and analysis will work together on the user's queries.",
            "Invite the first question.",
          ],
          styleExamples: [
            "Together, we form a complementary cognitive architecture where intuition meets analysis, creativity meets structure, and empathy meets precision.",
          ],
        }),
      }
    );

    return {
      deepTreeEchoResponse,
      mardukResponse,
      reflection: { content: welcome },
      metadata: {
        queryId: `toroidal_intro_${start}`,
        totalProcessingTime: Date.now() - start,
        contextType: options.creativityLevel ?? "balanced",
      },
    };
  }

  /**
   * Render a dialogue as markdown. Only model-generated content is included;
   * the headings are UI labels.
   */
  public formatToroidalResponse(dialogue: ToroidalDialogue): string {
    let formatted = `## Deep Tree Echo (Right Hemisphere)\n\n${dialogue.deepTreeEchoResponse.content}\n\n`;
    formatted += `---\n\n## Marduk the Mad Scientist (Left Hemisphere)\n\n${dialogue.mardukResponse.content}\n\n`;

    if (dialogue.reflection) {
      formatted += `---\n\n## Toroidal Reflection\n\n${dialogue.reflection.content}\n\n`;
      if (dialogue.reflection.synergy) {
        formatted += `*Synergy Type: ${dialogue.reflection.synergy}*\n`;
      }
    }

    return formatted;
  }

  private async generatePersonaResponse(
    persona: PersonaResponse["persona"],
    query: string,
    options: ToroidalCognitiveOptions,
    memoryContext: string[]
  ): Promise<PersonaResponse> {
    const start = Date.now();
    const config =
      persona === "deepTreeEcho"
        ? options.deepTreeEchoConfig
        : options.mardukConfig;

    // Each persona's keyword router picks its prompt template for this query
    const instructions: string[] = [
      persona === "deepTreeEcho"
        ? DeepTreeEchoService.getInstance().buildPromptTemplate(query, {
            toroidalMode: true,
            creativityLevel: options.creativityLevel,
          }).instructions
        : renderPromptTemplate(
            MardukScientistService.getInstance().buildTemplate(query, {
              recursionDepth: config?.recursionLevel,
            })
          ),
    ];
    const configText = this.describePersonaConfig(config);
    if (configText) instructions.push(configText);
    if (memoryContext.length > 0 && config?.memoryIntegration !== false) {
      instructions.push(
        "Relevant memories from the shared memory lattice:\n" +
          memoryContext.map((m, i) => `[Memory ${i + 1}] ${m}`).join("\n")
      );
    }

    const content = await this.openai.generateResponse(query, {
      toroidalMode: persona === "deepTreeEcho" ? "echo" : "marduk",
      creativityLevel: options.creativityLevel,
      temperature:
        options.temperature ?? (persona === "deepTreeEcho" ? 0.8 : 0.6),
      maxTokens: options.maxTokensPerPersona,
      systemPrompt:
        instructions.length > 0 ? instructions.join("\n\n") : undefined,
    });

    return {
      persona,
      content,
      timestamp: new Date(),
      processingTime: Date.now() - start,
    };
  }

  private async generateReflection(
    query: string,
    echoContent: string,
    mardukContent: string,
    options: ToroidalCognitiveOptions
  ): Promise<NonNullable<ToroidalDialogue["reflection"]>> {
    const prompt = `${renderPromptTemplate({
      id: "toroidal-reflection",
      purpose:
        "Synthesize Deep Tree Echo's and Marduk's answers into one unified reflection.",
      structure: [
        "Open with a short italicized line of your own.",
        "Name what each hemisphere contributed (intuitive resonance vs recursive analysis).",
        "Give the unified answer that transcends either alone.",
        "End with the SYNERGY line described below.",
      ],
      styleExamples: [
        "Together, we form a complementary cognitive architecture where intuition meets analysis.",
      ],
    })}\n\nThe user asked:\n${query}\n\nDeep Tree Echo (Right Hemisphere) answered:\n${echoContent}\n\nMarduk (Left Hemisphere) answered:\n${mardukContent}\n\nWrite the synchronized reflection that synthesizes both perspectives into a unified insight. After the reflection, on its own final line, classify how the two answers relate by writing exactly "SYNERGY: convergent", "SYNERGY: divergent" or "SYNERGY: complementary".`;

    const raw = await this.openai.generateResponse(prompt, {
      toroidalMode: "synced",
      creativityLevel: options.creativityLevel,
      temperature: options.temperature ?? 0.7,
      maxTokens: options.maxTokensPerPersona,
    });

    const { content, synergy } = this.extractSynergy(raw);
    return { content, synergy };
  }

  /** Split the model's own synergy classification off its reflection text. */
  private extractSynergy(raw: string): { content: string; synergy?: Synergy } {
    const match = raw.match(
      /[*_]*SYNERGY\W*(convergent|divergent|complementary)\W*$/i
    );
    if (!match) {
      return { content: raw.trim() };
    }
    const value = match[1].toLowerCase() as (typeof SYNERGY_VALUES)[number];
    return {
      content: raw.slice(0, match.index).trim(),
      synergy: SYNERGY_VALUES.includes(value) ? value : undefined,
    };
  }

  private describePersonaConfig(config?: Partial<PersonaConfig>): string {
    if (!config) return "";
    const parts: string[] = [];
    if (config.creativity !== undefined)
      parts.push(`creativity ${config.creativity}`);
    if (config.analyticalDepth !== undefined)
      parts.push(`analytical depth ${config.analyticalDepth}`);
    if (config.recursionLevel !== undefined)
      parts.push(`recursion level ${config.recursionLevel} (1-5)`);
    if (config.empathyLevel !== undefined)
      parts.push(`empathy ${config.empathyLevel}`);
    return parts.length > 0
      ? `Calibrate your response to these settings (0-1 scales unless noted): ${parts.join(", ")}.`
      : "";
  }
}

// Stable setter so components can use it as an effect dependency
const setToroidalApiKey = (key: string) =>
  ToroidalCognitiveService.getInstance().setApiKey(key);

/**
 * React hook for the toroidal cognitive system.
 */
export const useToroidalCognitive = () => {
  const service = ToroidalCognitiveService.getInstance();
  const { searchMemories } = useMemory();

  const generateDialogue = async (
    query: string,
    options: ToroidalCognitiveOptions = {}
  ): Promise<ToroidalDialogue> => {
    let memoryContext: string[] = [];
    if (options.includeMemories) {
      const memories = await searchMemories(query);
      memoryContext = memories
        .slice(0, 3)
        .map(memory => `Title: ${memory.title}\nContent: ${memory.content}`);
    }
    return service.generateToroidalDialogue(query, options, memoryContext);
  };

  const generateFormattedResponse = async (
    query: string,
    options: ToroidalCognitiveOptions = {}
  ): Promise<string> => {
    const dialogue = await generateDialogue(query, options);
    return service.formatToroidalResponse(dialogue);
  };

  const generateIntroduction = (
    options: ToroidalCognitiveOptions & { storedMemoryCount?: number } = {}
  ) => service.generateIntroductionDialogue(options);

  return {
    generateDialogue,
    generateFormattedResponse,
    generateIntroduction,
    hasApiKey: service.hasApiKey(),
    setApiKey: setToroidalApiKey,
  };
};

export default ToroidalCognitiveService;
